//! Test-only barriers at actual sidecar IO and a real cooperating writer process.
use std::{
    collections::HashMap,
    path::{Path, PathBuf},
    process::{Child, Command, Stdio},
    sync::{Mutex, OnceLock, mpsc},
    time::{Duration, Instant},
};

use anyhow::{Context, Result};
use tokio::sync::oneshot;

struct Hook {
    entered: oneshot::Sender<()>,
    resume: mpsc::Receiver<()>,
    finished: oneshot::Sender<()>,
}

fn hooks() -> &'static Mutex<HashMap<PathBuf, Hook>> {
    static HOOKS: OnceLock<Mutex<HashMap<PathBuf, Hook>>> = OnceLock::new();
    HOOKS.get_or_init(|| Mutex::new(HashMap::new()))
}

pub(crate) struct WritePause {
    path: PathBuf,
    entered: oneshot::Receiver<()>,
    release: Option<mpsc::Sender<()>>,
    finished: oneshot::Receiver<()>,
}

pub(crate) struct Completion(Option<oneshot::Sender<()>>);

impl Drop for Completion {
    fn drop(&mut self) {
        if let Some(done) = self.0.take() {
            let _ = done.send(());
        }
    }
}

pub(crate) fn pause_next_write(path: PathBuf) -> WritePause {
    let (entered, ready) = oneshot::channel();
    let (release, resume) = mpsc::channel();
    let (finished, done) = oneshot::channel();
    assert!(
        hooks()
            .lock()
            .expect("sidecar hooks")
            .insert(
                path.clone(),
                Hook {
                    entered,
                    resume,
                    finished
                }
            )
            .is_none(),
        "duplicate sidecar barrier"
    );
    WritePause {
        path,
        entered: ready,
        release: Some(release),
        finished: done,
    }
}

pub(crate) fn before_write(path: &Path) -> Result<Option<Completion>> {
    let hook = hooks().lock().expect("sidecar hooks").remove(path);
    let Some(Hook {
        entered,
        resume,
        finished,
    }) = hook
    else {
        return Ok(None);
    };
    let completion = Completion(Some(finished));
    let _ = entered.send(());
    resume
        .recv_timeout(Duration::from_secs(15))
        .context("sidecar IO barrier did not release")?;
    Ok(Some(completion))
}

impl WritePause {
    pub(crate) async fn entered(&mut self) {
        tokio::time::timeout(Duration::from_secs(10), &mut self.entered)
            .await
            .expect("sidecar worker reaches actual IO")
            .expect("sidecar entered signal");
    }

    pub(crate) fn release(&mut self) {
        if let Some(release) = self.release.take() {
            let _ = release.send(());
        }
    }

    pub(crate) async fn finished(&mut self) {
        tokio::time::timeout(Duration::from_secs(10), &mut self.finished)
            .await
            .expect("sidecar IO completes")
            .expect("sidecar finished signal");
    }
}

impl Drop for WritePause {
    fn drop(&mut self) {
        self.release();
        hooks().lock().expect("sidecar hooks").remove(&self.path);
    }
}

pub(crate) fn snapshot(profile: &str) -> crate::core::SessionConfigSnapshot {
    crate::core::SessionConfigSnapshot {
        schema_version: crate::core::SessionConfigSnapshot::SCHEMA_VERSION,
        ts: 1,
        profile_name: profile.to_owned(),
        active_provider: None,
        model: None,
        reasoning: Default::default(),
        modules: Default::default(),
        agent_control_surface: "none".to_owned(),
        tools: Vec::new(),
        permission_mode_default: crate::domain::PermissionMode::Normal,
        approval_available: false,
    }
}

pub(crate) async fn persisted(config: &Path, workspace: &Path) -> crate::core::SessionStore {
    let store = crate::core::SessionStore::new(config, workspace, crate::domain::new_session_id())
        .expect("store");
    store
        .append_history(
            crate::domain::new_thread_id(),
            None,
            &[crate::model_standard::CanonicalMessage::text(
                crate::model_standard::MessageRole::User,
                "sidecar seed",
            )],
        )
        .await
        .expect("clean canonical journal");
    crate::core::write_config_snapshot(store.session_dir(), &snapshot("seed"))
        .expect("seed snapshot");
    store
}

pub(crate) struct ChildWriter {
    child: Child,
    release: PathBuf,
    pub(crate) report: serde_json::Value,
}

impl ChildWriter {
    pub(crate) fn start(session: &Path, hold: bool) -> Self {
        let files = session.parent().expect("slot parent");
        let id = uuid::Uuid::new_v4();
        let report = files.join(format!(".sidecar-report-{id}.json"));
        let release = files.join(format!(".sidecar-release-{id}"));
        let child = Command::new(std::env::current_exe().expect("test executable"))
            .args([
                "--exact",
                "core::sidecar_test_support::owner_process_helper",
                "--ignored",
                "--test-threads=1",
            ])
            .env("PROTEUS_SIDECAR_TEST_SESSION", session)
            .env("PROTEUS_SIDECAR_TEST_REPORT", &report)
            .env("PROTEUS_SIDECAR_TEST_RELEASE", &release)
            .env("PROTEUS_SIDECAR_TEST_HOLD", if hold { "1" } else { "0" })
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::inherit())
            .spawn()
            .expect("writer process");
        let mut owner = Self {
            child,
            release,
            report: serde_json::Value::Null,
        };
        let deadline = Instant::now() + Duration::from_secs(10);
        while !report.exists() {
            if let Some(status) = owner.child.try_wait().expect("poll writer process") {
                panic!("writer process exited before report: {status}");
            }
            assert!(Instant::now() < deadline, "writer process report timeout");
            std::thread::sleep(Duration::from_millis(5));
        }
        owner.report = serde_json::from_slice(&std::fs::read(&report).expect("writer report"))
            .expect("complete writer report");
        std::fs::remove_file(report).expect("remove report");
        owner
    }

    pub(crate) fn finish(&mut self) {
        std::fs::write(&self.release, b"release").expect("release process");
        let deadline = Instant::now() + Duration::from_secs(10);
        loop {
            if let Some(status) = self.child.try_wait().expect("poll released writer") {
                assert!(status.success(), "writer helper failed: {status}");
                break;
            }
            assert!(Instant::now() < deadline, "writer process exit timeout");
            std::thread::sleep(Duration::from_millis(5));
        }
        let _ = std::fs::remove_file(&self.release);
    }
}

impl Drop for ChildWriter {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
        let _ = std::fs::remove_file(&self.release);
    }
}

pub(crate) async fn wait_for_lease_release(session: &Path) {
    let path = session.parent().expect("parent").join(format!(
        ".{}.write.lock",
        session.file_name().expect("name").to_string_lossy()
    ));
    let probe = std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open(path)
        .expect("lease probe");
    tokio::time::timeout(Duration::from_secs(10), async {
        loop {
            match probe.try_lock() {
                Ok(()) => break,
                Err(std::fs::TryLockError::WouldBlock) => {
                    tokio::time::sleep(Duration::from_millis(5)).await;
                }
                Err(error) => panic!("lease probe failed: {error}"),
            }
        }
    })
    .await
    .expect("worker releases final lease");
}

#[test]
#[ignore = "subprocess helper; invoked only with explicit isolated fixture paths"]
fn owner_process_helper() {
    let session = PathBuf::from(std::env::var_os("PROTEUS_SIDECAR_TEST_SESSION").expect("session"));
    let report = PathBuf::from(std::env::var_os("PROTEUS_SIDECAR_TEST_REPORT").expect("report"));
    let release = PathBuf::from(std::env::var_os("PROTEUS_SIDECAR_TEST_RELEASE").expect("release"));
    let hold = std::env::var("PROTEUS_SIDECAR_TEST_HOLD").expect("mode") == "1";
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let store = crate::core::SessionStore::open(session).expect("existing session");
    let attempt = runtime.block_on(store.append_history(
        crate::domain::new_thread_id(),
        None,
        &[crate::model_standard::CanonicalMessage::text(
            crate::model_standard::MessageRole::User,
            "foreign sidecar probe",
        )],
    ));
    let result = serde_json::json!({
        "ok": attempt.is_ok(),
        "error": attempt.as_ref().err().map(|error| format!("{error:#}")),
    });
    let temporary = report.with_extension("tmp");
    std::fs::write(
        &temporary,
        serde_json::to_vec(&result).expect("encode report"),
    )
    .expect("report");
    std::fs::rename(temporary, report).expect("publish complete report");
    if hold && attempt.is_ok() {
        let deadline = Instant::now() + Duration::from_secs(15);
        while !release.exists() {
            assert!(Instant::now() < deadline, "owner release timeout");
            std::thread::sleep(Duration::from_millis(5));
        }
    }
    drop(store);
}

pub(crate) fn image_input() -> crate::domain::UserMessageInput {
    crate::domain::UserMessageInput {
        text: "sidecar image".to_owned(),
        images: vec![
            crate::domain::ImageAttachment::from_bytes(
                "pixel.png".to_owned(),
                include_bytes!("../../tests/fixtures/pixel.png"),
            )
            .expect("fixture image"),
        ],
    }
}

fn delete_observers() -> &'static Mutex<HashMap<PathBuf, oneshot::Sender<bool>>> {
    static OBSERVERS: OnceLock<Mutex<HashMap<PathBuf, oneshot::Sender<bool>>>> = OnceLock::new();
    OBSERVERS.get_or_init(|| Mutex::new(HashMap::new()))
}

pub(crate) struct DeleteObservation {
    path: PathBuf,
    observed: oneshot::Receiver<bool>,
}

pub(crate) fn observe_next_delete_lock(path: PathBuf) -> DeleteObservation {
    let (report, observed) = oneshot::channel();
    assert!(
        delete_observers()
            .lock()
            .expect("delete observers")
            .insert(path.clone(), report)
            .is_none()
    );
    DeleteObservation { path, observed }
}

impl DeleteObservation {
    pub(crate) async fn was_pending(&mut self) -> bool {
        tokio::time::timeout(Duration::from_secs(10), &mut self.observed)
            .await
            .expect("owned deletion reaches actual writer lock")
            .expect("owned deletion lock observation")
    }
}

impl Drop for DeleteObservation {
    fn drop(&mut self) {
        delete_observers()
            .lock()
            .expect("delete observers")
            .remove(&self.path);
    }
}

/// Observe the first poll without dropping a Ready guard or introducing a gap.
pub(crate) async fn observe_delete_lock<F: std::future::Future>(
    path: &Path,
    future: F,
) -> F::Output {
    let mut future = std::pin::pin!(future);
    let mut observer = delete_observers()
        .lock()
        .expect("delete observers")
        .remove(path);
    std::future::poll_fn(move |context| {
        let result = std::future::Future::poll(future.as_mut(), context);
        if let Some(observer) = observer.take() {
            let _ = observer.send(result.is_pending());
        }
        result
    })
    .await
}

