use super::*;
use crate::core::sidecar_test_support::{ChildWriter, persisted, snapshot};
use crate::core::{SessionStore, delete_workspace_session};
use crate::domain::new_thread_id;
use crate::model_standard::{CanonicalMessage, MessageRole};
use std::time::Duration;

#[tokio::test]
async fn public_snapshot_does_not_recreate_missing_session() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = persisted(config.path(), workspace.path()).await;
    let path = store.session_dir().to_owned();
    drop(store);
    assert!(
        delete_workspace_session(config.path(), workspace.path(), path.clone())
            .await
            .unwrap()
    );
    let result = write_config_snapshot(&path, &snapshot("late"));
    assert!(
        result.is_err(),
        "CONFIG_MISSING_NO_RECREATE: missing session must be rejected"
    );
    assert!(
        !path.exists(),
        "CONFIG_MISSING_NO_RECREATE: snapshot must not recreate storage"
    );
}

#[test]
fn public_snapshot_rejects_invalid_existing_directory_without_writing() {
    let root = tempfile::tempdir().unwrap();
    let path = root.path().join("not-a-session");
    std::fs::create_dir(&path).unwrap();
    let result = write_config_snapshot(&path, &snapshot("invalid"));
    assert!(
        result.is_err(),
        "CONFIG_INVALID_IDENTITY: invalid session must be rejected"
    );
    assert_eq!(std::fs::read_dir(path).unwrap().count(), 0);
}

#[tokio::test]
async fn public_snapshot_respects_foreign_writer_and_then_succeeds() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = persisted(config.path(), workspace.path()).await;
    let path = store.session_dir().to_owned();
    drop(store);
    let mut owner = ChildWriter::start(&path, true);
    assert_eq!(owner.report["ok"], true, "foreign owner setup");
    let journal = std::fs::read(path.join("journal.jsonl")).unwrap();
    let before = std::fs::read(path.join(CONFIG_SNAPSHOT_FILE)).unwrap();
    let result = write_config_snapshot(&path, &snapshot("foreign mutation"));
    let after = std::fs::read(path.join(CONFIG_SNAPSHOT_FILE)).unwrap();
    owner.finish();
    assert!(
        result.is_err(),
        "CONFIG_FOREIGN_OWNER: must reject a foreign live writer"
    );
    assert_eq!(after, before, "foreign rejection changed snapshot");
    assert_eq!(std::fs::read(path.join("journal.jsonl")).unwrap(), journal);
    write_config_snapshot(&path, &snapshot("after owner")).unwrap();
    let saved: SessionConfigSnapshot =
        serde_json::from_slice(&std::fs::read(path.join(CONFIG_SNAPSHOT_FILE)).unwrap()).unwrap();
    assert_eq!(saved.profile_name, "after owner");
    assert_eq!(saved.schema_version, SessionConfigSnapshot::SCHEMA_VERSION);
    assert_eq!(std::fs::read(path.join("journal.jsonl")).unwrap(), journal);
}

#[tokio::test]
async fn public_snapshot_reuses_idle_local_owner_without_journal_change() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = persisted(config.path(), workspace.path()).await;
    let journal = std::fs::read(store.journal_path()).unwrap();
    write_config_snapshot(store.session_dir(), &snapshot("same generation")).unwrap();
    assert_eq!(std::fs::read(store.journal_path()).unwrap(), journal);
    assert!(
        delete_workspace_session(
            config.path(),
            workspace.path(),
            store.session_dir().to_owned()
        )
        .await
        .is_err(),
        "snapshot did not release the legitimate writer"
    );
    let saved: SessionConfigSnapshot = serde_json::from_slice(
        &std::fs::read(store.session_dir().join(CONFIG_SNAPSHOT_FILE)).unwrap(),
    )
    .unwrap();
    assert_eq!(saved.profile_name, "same generation");
}

#[tokio::test]
async fn synchronous_snapshot_contention_returns_busy_without_deadlock() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = persisted(config.path(), workspace.path()).await;
    let before = std::fs::read(store.session_dir().join(CONFIG_SNAPSHOT_FILE)).unwrap();
    let (entered, release) = store.pause_next_append().await;
    struct Release(Option<std::sync::mpsc::Sender<bool>>);
    impl Drop for Release {
        fn drop(&mut self) {
            if let Some(sender) = self.0.take() {
                let _ = sender.send(true);
            }
        }
    }
    let release = Release(Some(release));
    let appending = store.clone();
    let task = tokio::spawn(async move {
        appending
            .append_history(
                new_thread_id(),
                None,
                &[CanonicalMessage::text(MessageRole::User, "paused append")],
            )
            .await
    });
    tokio::time::timeout(Duration::from_secs(10), entered)
        .await
        .unwrap()
        .unwrap();
    // Deliberately call the synchronous public API from a Tokio worker.
    let result = write_config_snapshot(store.session_dir(), &snapshot("contending"));
    let after = std::fs::read(store.session_dir().join(CONFIG_SNAPSHOT_FILE)).unwrap();
    drop(release);
    tokio::time::timeout(Duration::from_secs(10), task)
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    assert!(
        result.is_err(),
        "CONFIG_SYNC_CONTENTION: busy synchronous writer must reject"
    );
    assert_eq!(after, before);
    write_config_snapshot(store.session_dir(), &snapshot("after contention")).unwrap();
}

#[tokio::test]
async fn snapshot_io_failure_preserves_an_existing_owner() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = persisted(config.path(), workspace.path()).await;
    let path = store.session_dir().join(CONFIG_SNAPSHOT_FILE);
    std::fs::remove_file(&path).unwrap();
    std::fs::create_dir(&path).unwrap();
    assert!(write_config_snapshot(store.session_dir(), &snapshot("IO failure")).is_err());
    let mut other = ChildWriter::start(store.session_dir(), false);
    assert_eq!(
        other.report["ok"], false,
        "existing writer must survive body IO error"
    );
    assert!(
        other.report["error"]
            .as_str()
            .unwrap()
            .contains("active writer")
    );
    other.finish();
    std::fs::remove_dir(&path).unwrap();
    write_config_snapshot(store.session_dir(), &snapshot("recovered")).unwrap();
    assert_eq!(
        SessionStore::open(store.session_dir().to_owned())
            .unwrap()
            .session_id(),
        store.session_id()
    );
}

#[tokio::test]
async fn snapshot_recovery_rejection_releases_only_new_lease() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let seed = persisted(config.path(), workspace.path()).await;
    let path = seed.session_dir().to_owned();
    let journal = std::fs::read(seed.journal_path()).unwrap();
    let before = std::fs::read(path.join(CONFIG_SNAPSHOT_FILE)).unwrap();
    drop(seed);
    let cold = SessionStore::open(path.clone()).unwrap();
    std::fs::write(cold.journal_path(), b"{invalid complete record}\n").unwrap();
    let result = write_config_snapshot(&path, &snapshot("invalid journal"));
    let after = std::fs::read(path.join(CONFIG_SNAPSHOT_FILE)).unwrap();
    std::fs::write(cold.journal_path(), journal).unwrap();
    let mut contender = ChildWriter::start(&path, false);
    assert_eq!(
        contender.report["ok"], true,
        "failed preflight must release newly acquired lease"
    );
    contender.finish();
    assert!(
        result.is_err(),
        "CONFIG_RECOVERY_PREFLIGHT: snapshot must validate the canonical writer"
    );
    assert_eq!(after, before);
}

