use super::*;
use crate::core::sidecar_test_support::{persisted, snapshot};
use crate::core::{CONFIG_SNAPSHOT_FILE, write_config_snapshot};
use std::time::Duration;

#[tokio::test]
async fn public_snapshot_rejects_retired_generation_before_removal() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = persisted(config.path(), workspace.path()).await;
    let path = store.session_dir().to_owned();
    let before = std::fs::read(path.join(CONFIG_SNAPSHOT_FILE)).unwrap();
    let (entered, ready) = tokio::sync::oneshot::channel();
    let (release, resume) = std::sync::mpsc::channel();
    struct Release(Option<std::sync::mpsc::Sender<()>>);
    impl Drop for Release {
        fn drop(&mut self) {
            if let Some(sender) = self.0.take() {
                let _ = sender.send(());
            }
        }
    }
    let release = Release(Some(release));
    let deleting = store.clone();
    let root = config.path().to_owned();
    let cwd = workspace.path().to_owned();
    let task = tokio::spawn(async move {
        deleting
            .delete_owned_with(&root, &cwd, move || {
                let _ = entered.send(());
                resume.recv_timeout(Duration::from_secs(15))?;
                Ok(())
            })
            .await
    });
    tokio::time::timeout(Duration::from_secs(10), ready)
        .await
        .unwrap()
        .unwrap();
    assert!(path.exists(), "retired directory remains during probe");
    let result = write_config_snapshot(&path, &snapshot("retired"));
    let after = std::fs::read(path.join(CONFIG_SNAPSHOT_FILE)).unwrap();
    drop(release);
    assert!(
        tokio::time::timeout(Duration::from_secs(10), task)
            .await
            .unwrap()
            .unwrap()
            .unwrap()
    );
    assert!(!path.exists());
    assert!(
        result.is_err(),
        "CONFIG_RETIRED_GENERATION: retired generation must reject snapshot"
    );
    assert_eq!(after, before);
}

