use super::*;
use crate::core::sidecar_test_support::{
    ChildWriter, image_input, observe_next_delete_lock, pause_next_write, wait_for_lease_release,
};
use std::time::Duration;

async fn launch(config: &std::path::Path, workspace: &std::path::Path) -> AppServerHandle {
    AgentAppServer::launch(
        crate::test_model::config(),
        workspace.to_owned(),
        Some(&config.join("config.toml")),
    )
    .await
    .expect("image sidecar server")
}

#[tokio::test]
async fn canceled_image_admission_worker_retains_final_writer_owner() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let server = launch(config.path(), workspace.path()).await;
    let path = server.session_dir_path().unwrap();
    let mut pause = pause_next_write(path.join("images"));
    let admission_server = server.clone();
    let admission = tokio::spawn(async move {
        admission_server
            .admit_user_message(
                None,
                image_input(),
                Default::default(),
                CancellationToken::new(),
                true,
            )
            .await
            .map(|_| ())
    });
    pause.entered().await;
    admission.abort();
    assert!(admission.await.unwrap_err().is_cancelled());
    server.shutdown().await;
    drop(server);
    let mut contender = ChildWriter::start(&path, false);
    let blocked = contender.report["ok"] == false
        && contender.report["error"]
            .as_str()
            .is_some_and(|error| error.contains("active writer"));
    contender.finish();
    pause.release();
    pause.finished().await;
    wait_for_lease_release(&path).await;
    let mut after = ChildWriter::start(&path, false);
    assert_eq!(
        after.report["ok"], true,
        "owner releases after actual image IO"
    );
    after.finish();
    assert!(
        blocked,
        "IMAGE_CANCELED_OWNER: detached image IO must retain the final owner"
    );
}

#[tokio::test]
async fn canceled_image_admission_is_ordered_before_owned_deletion() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let server = launch(config.path(), workspace.path()).await;
    let path = server.session_dir_path().unwrap();
    let mut pause = pause_next_write(path.join("images"));
    let admission_server = server.clone();
    let admission = tokio::spawn(async move {
        admission_server
            .admit_user_message(
                None,
                image_input(),
                Default::default(),
                CancellationToken::new(),
                true,
            )
            .await
            .map(|_| ())
    });
    pause.entered().await;
    admission.abort();
    assert!(admission.await.unwrap_err().is_cancelled());
    let mut observation = observe_next_delete_lock(path.clone());
    let deleting_server = server.clone();
    let deleting_path = path.clone();
    let mut deletion = tokio::spawn(async move {
        deleting_server
            .delete_workspace_session(deleting_path)
            .await
    });
    // The signal reports the actual first lock poll, not elapsed wall time.
    // On the baseline Ready path, finish deletion while image IO is paused.
    let waited_for_image = observation.was_pending().await;
    if !waited_for_image {
        assert!(
            tokio::time::timeout(Duration::from_secs(10), &mut deletion)
                .await
                .expect("unblocked deletion completes")
                .unwrap()
                .unwrap()
        );
    }
    pause.release();
    pause.finished().await;
    if waited_for_image {
        assert!(
            tokio::time::timeout(Duration::from_secs(10), deletion)
                .await
                .expect("deletion follows image IO")
                .unwrap()
                .unwrap()
        );
    }
    assert!(
        waited_for_image && !path.exists(),
        "IMAGE_CANCELED_DELETE: deletion must follow actual image IO with no late recreation"
    );
}

#[tokio::test]
async fn foreign_owner_rejects_image_before_materialization() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let seed = launch(config.path(), workspace.path()).await;
    let store = seed.runtime.session_store().unwrap().clone();
    store
        .append_history(
            new_thread_id(),
            None,
            &[crate::model_standard::CanonicalMessage::text(
                crate::model_standard::MessageRole::User,
                "seed",
            )],
        )
        .await
        .unwrap();
    let path = store.session_dir().to_owned();
    seed.shutdown().await;
    drop(store);
    drop(seed);
    let mut owner = ChildWriter::start(&path, true);
    assert_eq!(owner.report["ok"], true);
    let server = AgentAppServer::launch_resumed(
        crate::test_model::config(),
        workspace.path().to_owned(),
        Some(&config.path().join("config.toml")),
        path.clone(),
    )
    .await
    .unwrap();
    let journal = std::fs::read(path.join("journal.jsonl")).unwrap();
    let result = server
        .admit_user_message(
            None,
            image_input(),
            Default::default(),
            CancellationToken::new(),
            true,
        )
        .await;
    assert!(result.is_err(), "foreign image admission must fail");
    assert!(!path.join("images").exists());
    assert_eq!(std::fs::read(path.join("journal.jsonl")).unwrap(), journal);
    server.shutdown().await;
    owner.finish();
}

#[tokio::test]
async fn retired_server_rejects_image_without_recreation() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let server = launch(config.path(), workspace.path()).await;
    let path = server.session_dir_path().unwrap();
    server.delete_workspace_session(path.clone()).await.unwrap();
    let result = server
        .admit_user_message(
            None,
            image_input(),
            Default::default(),
            CancellationToken::new(),
            true,
        )
        .await;
    assert!(result.is_err());
    assert!(!path.exists());
}

