fn message_text_for_test(message: &CanonicalMessage) -> String {
    message
        .parts
        .iter()
        .filter_map(|part| match &part.payload {
            crate::model_standard::ContentPart::Text { text } => Some(text.as_str()),
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("\n")
