use std::{
    path::Path,
    time::{SystemTime, UNIX_EPOCH},
};

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};

use crate::{
    core::{AppConfig, ModulesConfig, RuntimeRegistry},
    domain::{ModelRef, PermissionMode, ReasoningConfig, ToolSpec},
};

pub const CONFIG_SNAPSHOT_FILE: &str = "config_snapshot.json";

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SessionConfigSnapshot {
    pub schema_version: u32,
    pub ts: u64,
    pub profile_name: String,
    pub active_provider: Option<String>,
    pub model: Option<ModelRef>,
    pub reasoning: ReasoningConfig,
    pub modules: SessionConfigModules,
    pub agent_control_surface: String,
    pub tools: Vec<SessionConfigTool>,
    pub permission_mode_default: PermissionMode,
    /// Actual approval transport capability captured for this execution.
    pub approval_available: bool,
}

pub type SessionConfigModules = ModulesConfig;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SessionConfigTool {
    pub source: String,
    pub spec: ToolSpec,
    pub model_visible: bool,
}

impl SessionConfigTool {
    pub(crate) fn capture(registry: &crate::contracts::ToolRegistry) -> Vec<Self> {
        registry
            .entries()
            .into_iter()
            .map(|(source, spec)| Self {
                source: source.label(),
                model_visible: registry
                    .get(&spec.name)
                    .expect("registry entry has a registered tool")
                    .model_visible(),
                spec,
            })
            .collect()
    }
}

impl SessionConfigSnapshot {
    pub const SCHEMA_VERSION: u32 = 8;

    pub fn from_runtime_config(
        config: &AppConfig,
        registry: &RuntimeRegistry,
        permission_mode_default: PermissionMode,
        approval_available: bool,
    ) -> Self {
        let tools = SessionConfigTool::capture(&registry.tools);
        Self {
            schema_version: Self::SCHEMA_VERSION,
            ts: unix_timestamp_ms(),
            profile_name: config.profile.name.clone(),
            active_provider: config.active_provider.clone(),
            model: registry.model_config.as_ref().map(|cfg| cfg.model_ref()),
            reasoning: registry
                .model_config
                .as_ref()
                .map(|cfg| cfg.reasoning.clone())
                .unwrap_or_default(),
            modules: config.modules.clone(),
            agent_control_surface: config.agent_control.surface.as_str().to_owned(),
            tools,
            permission_mode_default,
            approval_available,
        }
    }
}

fn unix_timestamp_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis().try_into().unwrap_or(u64::MAX))
        .unwrap_or(0)
}

/// Write a snapshot for an existing, validated session without waiting for a
/// busy writer. Read-only resume must not call this mutating API.
pub fn write_config_snapshot(session_dir: &Path, snapshot: &SessionConfigSnapshot) -> Result<()> {
    crate::core::SessionStore::open(session_dir.to_path_buf())?.write_config_snapshot_now(snapshot)
}

/// The caller holds the active generation's writer guard and committed lease.
/// This sidecar is best effort, not atomic with the canonical journal.
pub(super) fn write_existing_config_snapshot(
    session_dir: &Path,
    snapshot: &SessionConfigSnapshot,
) -> Result<()> {
    let path = session_dir.join(CONFIG_SNAPSHOT_FILE);
    let mut content = serde_json::to_vec_pretty(snapshot)?;
    content.push(b'\n');
    #[cfg(test)]
    let _completion = crate::core::sidecar_test_support::before_write(&path)?;
    std::fs::write(&path, content)
        .with_context(|| format!("failed to write {}", path.display()))?;
    Ok(())
}

