use super::*;
use crate::core::sidecar_test_support::{ChildWriter, persisted};
use crate::core::{CONFIG_SNAPSHOT_FILE, SessionStore};
use crate::domain::new_thread_id;

async fn check_resume(cached: bool) {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = persisted(config.path(), workspace.path()).await;
    let path = store.session_dir().to_owned();
    let saved_history = store.conversation_snapshot().unwrap();
    drop(store);
    let mut foreign = ChildWriter::start(&path, true);
    assert_eq!(foreign.report["ok"], true, "foreign owner setup");
    let before = std::fs::read(path.join(CONFIG_SNAPSHOT_FILE)).unwrap();
    let journal = std::fs::read(path.join("journal.jsonl")).unwrap();
    let cold = SessionStore::open(path.clone()).unwrap();
    let mut next = AppConfig::default();
    next.profile.name = "read-only resume config".to_owned();
    let builder = AgentRuntime::builder(next, workspace.path().to_owned())
        .with_module_catalog(test_catalog())
        .with_config_path(Some(&config.path().join("config.toml")));
    let builder = if cached {
        builder.resume_from_session_snapshot(cold, saved_history, new_thread_id(), true)
    } else {
        builder.resume_from_session_store(cold, new_thread_id())
    };
    let runtime = builder
        .build()
        .expect("display-only resume works under a foreign owner");
    let after = std::fs::read(path.join(CONFIG_SNAPSHOT_FILE)).unwrap();
    assert_eq!(
        runtime
            .snapshot()
            .await
            .config_snapshot
            .unwrap()
            .profile_name,
        "read-only resume config",
        "fresh config remains available in memory"
    );
    assert!(!path.join("images").exists());
    assert_eq!(std::fs::read(path.join("journal.jsonl")).unwrap(), journal);
    foreign.finish();
    // The resumed runtime is still live but must not acquire the writer lease.
    let mut contender = ChildWriter::start(&path, false);
    assert_eq!(
        contender.report["ok"], true,
        "read-only resume must not own the writer"
    );
    contender.finish();
    if cached {
        assert!(
            after == before,
            "CACHED_RESUME_SNAPSHOT_READ_ONLY: cached display must not overwrite snapshot"
        );
    } else {
        assert!(
            after == before,
            "COLD_RESUME_SNAPSHOT_READ_ONLY: cold display must not overwrite snapshot"
        );
    }
}

#[tokio::test]
async fn cold_resume_preserves_snapshot_and_stays_read_only() {
    check_resume(false).await;
}

#[tokio::test]
async fn cached_resume_preserves_snapshot_and_stays_read_only() {
    check_resume(true).await;
}

#[tokio::test]
async fn text_only_and_nonpersistent_image_admission_keep_existing_semantics() {
    let workspace = tempfile::tempdir().unwrap();
    let runtime = AgentRuntime::builder(AppConfig::default(), workspace.path().to_owned())
        .with_module_catalog(test_catalog())
        .with_config_path(Some(&workspace.path().join("config.toml")))
        .build()
        .unwrap();
    let text = runtime
        .reserve_user_message("text only".to_owned())
        .await
        .unwrap();
    assert!(
        !runtime.session_dir().unwrap().exists(),
        "text admission stays lazy"
    );
    assert!(!workspace.path().join("images").exists());
    drop(text);
    // Use a separate runtime: dropping a reservation is not a turn settlement.
    let runtime = AgentRuntime::builder(AppConfig::default(), workspace.path().to_owned())
        .with_module_catalog(test_catalog())
        .build()
        .unwrap();
    let reserved = runtime
        .reserve_user_message_with_options(
            crate::core::sidecar_test_support::image_input(),
            Default::default(),
        )
        .await
        .unwrap();
    assert!(runtime.session_dir().is_none());
    assert_eq!(
        std::fs::read_dir(workspace.path().join("images"))
            .unwrap()
            .count(),
        1
    );
    drop(reserved);
}

