    assert!(message_text_for_test(&history[1]).contains("current request"));
    assert!(message_text_for_test(&history[2]).contains("done after compact"));

    let stored = runtime
        .session
        .session_store
        .as_ref()
        .expect("session store")
        .load_messages()
        .expect("load replaced messages");
    assert_eq!(stored, history);
    let snapshot = runtime.conversation_snapshot().await.unwrap();
    assert_eq!(snapshot.messages, history);
    assert_eq!(
        snapshot.model_context,
        vec![crate::contracts::ModelContextObservation::HistoryCompacted]
    );
    assert_eq!(
        snapshot,
        runtime
            .session
            .session_store
            .as_ref()
            .unwrap()
            .conversation_snapshot()
            .unwrap()
    );
}

