use super::*;
use crate::core::CONFIG_SNAPSHOT_FILE;
use crate::core::attachments::ImageStore;
use crate::core::sidecar_test_support::{
    ChildWriter, image_input, pause_next_write, persisted, snapshot, wait_for_lease_release,
};

#[tokio::test]
async fn canceled_snapshot_worker_retains_final_owner_until_io_finishes() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = persisted(config.path(), workspace.path()).await;
    let path = store.session_dir().to_owned();
    let mut pause = pause_next_write(path.join(CONFIG_SNAPSHOT_FILE));
    let writing = store.clone();
    let task = tokio::spawn(async move {
        writing
            .persist_config_snapshot(snapshot("owned async write"))
            .await
    });
    pause.entered().await;
    task.abort();
    assert!(task.await.unwrap_err().is_cancelled());
    drop(store);
    let mut contender = ChildWriter::start(&path, false);
    assert_eq!(
        contender.report["ok"], false,
        "snapshot worker retains the only writer owner"
    );
    contender.finish();
    pause.release();
    pause.finished().await;
    wait_for_lease_release(&path).await;
    let saved: crate::core::SessionConfigSnapshot =
        serde_json::from_slice(&std::fs::read(path.join(CONFIG_SNAPSHOT_FILE)).unwrap()).unwrap();
    assert_eq!(saved.profile_name, "owned async write");
    let mut next = ChildWriter::start(&path, false);
    assert_eq!(next.report["ok"], true);
    next.finish();
}

#[tokio::test]
async fn retired_store_rejects_config_and_images_without_recreation() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = persisted(config.path(), workspace.path()).await;
    let path = store.session_dir().to_owned();
    assert!(
        store
            .delete_owned(config.path(), workspace.path())
            .await
            .unwrap()
    );
    let config_error = store
        .persist_config_snapshot(snapshot("retired"))
        .await
        .unwrap_err();
    let image_error = store
        .admit_images(ImageStore::prepare(image_input()).unwrap())
        .await
        .unwrap_err();
    assert!(config_error.to_string().contains("retired"));
    assert!(image_error.to_string().contains("retired"));
    assert!(!path.exists());
}

#[tokio::test]
async fn image_first_write_materializes_identity_and_preserves_content_addressing() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = SessionStore::new(
        config.path(),
        workspace.path(),
        crate::domain::new_session_id(),
    )
    .unwrap();
    assert!(!store.session_dir().exists(), "construction remains lazy");
    let first = store
        .admit_images(ImageStore::prepare(image_input()).unwrap())
        .await
        .unwrap();
    let second = store
        .admit_images(ImageStore::prepare(image_input()).unwrap())
        .await
        .unwrap();
    let first = first.image_refs().next().unwrap();
    let second = second.image_refs().next().unwrap();
    assert_eq!(first.id, second.id);
    assert_eq!(first.path, second.path);
    assert_eq!(
        std::fs::read(&first.path).unwrap(),
        include_bytes!("../../../tests/fixtures/pixel.png")
    );
    assert_eq!(
        SessionStore::open(store.session_dir().to_owned())
            .unwrap()
            .session_id(),
        store.session_id()
    );
    assert!(
        store.load_messages().unwrap().is_empty(),
        "image sidecar is not a journal commit"
    );
    assert_eq!(
        std::fs::read_dir(store.session_dir().join("images"))
            .unwrap()
            .count(),
        1
    );
}

#[tokio::test]
async fn image_io_failure_preserves_owner_and_allows_retry() {
    let config = tempfile::tempdir().unwrap();
    let workspace = tempfile::tempdir().unwrap();
    let store = persisted(config.path(), workspace.path()).await;
    let root = store.session_dir().join("images");
    std::fs::write(&root, b"blocking file").unwrap();
    assert!(
        store
            .admit_images(ImageStore::prepare(image_input()).unwrap())
            .await
            .is_err()
    );
    let mut contender = ChildWriter::start(store.session_dir(), false);
    assert_eq!(contender.report["ok"], false);
    contender.finish();
    std::fs::remove_file(root).unwrap();
    store
        .admit_images(ImageStore::prepare(image_input()).unwrap())
        .await
        .unwrap();
}
